import json, os, glob

def migrate_config(data):
    """Migrate a v1 config dict to v2."""
    result = {}

    # version
    result["version"] = 2

    # Every other key
    for key, value in data.items():
        if key == "version":
            continue
        elif key == "timeoutMs":
            result["timeout_s"] = value / 1000.0
        elif key == "retry":
            result["retry"] = {
                "attempts": value["count"],
                "backoff_s": value["backoffMs"] / 1000.0
            }
        elif key == "owners":
            # comma-separated string -> array of trimmed, lower-cased, non-empty emails, original order
            if isinstance(value, str):
                parts = [part.strip().lower() for part in value.split(",")]
                parts = [p for p in parts if p]
                result["owners"] = parts
            else:
                result["owners"] = value
        else:
            result[key] = value

    # If retry missing, add default
    if "retry" not in result:
        result["retry"] = { "attempts": 0, "backoff_s": 0 }

    return result

